BEGIN;
ALTER TABLE base_evaluacion ADD COLUMN IF NOT EXISTS baterias_incluidas_por_receptor INTEGER CHECK (baterias_incluidas_por_receptor > 0);
ALTER TABLE base_evaluacion ADD COLUMN IF NOT EXISTS inclinacion_imu_deg NUMERIC CHECK (inclinacion_imu_deg BETWEEN 0 AND 180);
ALTER TABLE base_evaluacion ADD COLUMN IF NOT EXISTS actualizacion_hz NUMERIC CHECK (actualizacion_hz >= 0);
ALTER TABLE base_evaluacion ADD COLUMN IF NOT EXISTS usb BOOLEAN;
ALTER TABLE base_evaluacion ADD COLUMN IF NOT EXISTS usb_c BOOLEAN;
ALTER TABLE base_evaluacion ADD COLUMN IF NOT EXISTS rs232 BOOLEAN;
ALTER TABLE base_evaluacion ADD COLUMN IF NOT EXISTS auditoria_fuente TEXT;
ALTER TABLE base_evaluacion ADD COLUMN IF NOT EXISTS auditoria_notas TEXT;
ALTER TABLE controladora_especificaciones ADD COLUMN IF NOT EXISTS brujula BOOLEAN;
UPDATE base_evaluacion SET peso_max=NULL, lemo=TRUE, lemo_pines=7, baterias_incluidas_por_receptor=2, usb=TRUE, rs232=TRUE, actualizacion_hz=10, caida_m=2, auditoria_fuente='ficha_tecnica_GPS-CHC-GNSS-i50.pdf; páginas 1–3; auditoría 2026-09-18.', auditoria_notas='Peso no legible/declarado en la tabla aportada: requiere confirmación. Kit de 2 receptores con 4 baterías: 2 incluidas por receptor. Autonomía celular hasta 10 h; UHF 5–7 h. LEMO 7 pines confirmado visualmente en p.3.' WHERE id_equipo='GNSS-CHCNAV-I50';
