UPDATE base_evaluacion SET peso_max=730, inclinacion_imu_deg=60, actualizacion_hz=NULL, tiene_ppp=TRUE, largo_static_horizontal_mm=2.5, largo_static_vertical_mm=3.5, largo_static_ppm_h=0.1, largo_static_ppm_v=0.4, usb=TRUE, usb_c=TRUE, auditoria_fuente='i73+_DS_EN.pdf; páginas 2,4; auditoría 2026-09-18.', auditoria_notas='Rover hasta 24 h; base UHF 10.5 h. Especificación 60° en tabla y precisión a 30° en texto. Señales con asterisco y salida 10 Hz sujetas a firmware.' WHERE id_equipo='GNSS-CHCNAV-I73PLUS';
UPDATE base_evaluacion SET canales_gnss=1892, peso_max=1150, autonomia_bateria=34, static_ppm_h=0.5, mp_camara=5, proteccion_ip='IP68', vibracion_norma='MIL-STD-810H', bluetooth_version='5.0 y 4.2 + EDR', wifi_estandar='802.11 a/b/g/n/ac', tipo_bateria='Li-ion interna no extraíble, 9900 mAh, 7.2 V', memoria_expandible=TRUE, memoria_expandida_max_gb=128, inclinacion_imu_deg=60, actualizacion_hz=NULL, usb=TRUE, usb_c=TRUE, rs232=TRUE, largo_static_horizontal_mm=2.5, largo_static_vertical_mm=3.5, largo_static_ppm_h=0.1, largo_static_ppm_v=0.4, auditoria_fuente='i93_DS_EN.pdf; páginas 1–4; auditoría 2026-09-18.', auditoria_notas='Ficha marzo 2026: 1892 canales, 9900 mAh, IP68 y rover sin cámara hasta 34 h; visual hasta 24 h. Confirmar que el equipo ofertado es esta revisión. 10 Hz, señales marcadas y PointSky dependen de firmware/servicio. Noticia oficial tiene fecha 2023 y texto 2022: año exacto pendiente.' WHERE id_equipo='GNSS-CHCNAV-I93';
UPDATE base_evaluacion SET peso_max=950, largo_mm=126, ancho_mm=126, alto_mm=142, tiempo_inicializacion=5, autonomia_bateria=16, actualizacion_hz=5, usb=TRUE, usb_c=TRUE, rs232=TRUE, sim_4g=FALSE, auditoria_fuente='Datasheet RS2 ENG web.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='Autonomía usada: modo rover RTK (RS2/RS2+ 16 h; RS3 con inclinación 18 h), no las 22 h de registro. ~5 s es convergencia RTK, no encendido. RS2 tiene módem 3.5G, no LTE.' WHERE id_equipo='GNSS-EMLID-RS2';
