UPDATE base_evaluacion SET peso_max=930, tiempo_inicializacion=4, sim_4g=FALSE, lte_4g=FALSE, wifi=NULL, bluetooth_version='2.00 + EDR', proteccion_ip='IP68', temperatura_almacenamiento_max_c=80, tiene_ppp=TRUE, ppp_h_cm=3, memoria_expandible=TRUE, radio_frecuencia='403-470 MHz', usb=TRUE, rs232=TRUE, actualizacion_hz=20, navic_irnss=NULL, constelaciones=5, auditoria_fuente='Leica_Viva_GS16_GNSS_smart_antenna_DS.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='Ficha 11.17: 0.93 kg, módem 3.75G; no importar Wi-Fi/LTE de GS18. RINEX y constelaciones/licencias según versión; NavIC futura actualización. SmartLink PPP opcional, H 3 cm. Memoria microSD, no memoria interna.' WHERE id_equipo='GNSS-LEICA-GS16';
