UPDATE base_evaluacion SET inclinacion_imu_deg=60, tiempo_inicializacion=5, actualizacion_hz=50, usb=TRUE, usb_c=TRUE, bateria_interna=TRUE, bateria_intercambiable=NULL, bateria_caliente=NULL, auditoria_fuente='X1 GNSS Receiver.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='Inicialización RTK <5 s, no encendido. Rango IMU 60°. La expansión de memoria es capacidad soportada, no instalada. No inferir baterías de repuesto. Catálogo oficial confirma batería integrada. Intercambio y cambio en caliente no declarados. UHF mejorada LoRa Tx/Rx; protocolo de otras marcas Rx o módulo normal opcional: confirmar variante.' WHERE id_equipo='GNSS-SINGULARXYZ-X1';
UPDATE equipos SET anio_modelo=2023 WHERE id_equipo='GNSS-SINGULARXYZ-X1';
UPDATE base_evaluacion SET inclinacion_imu_deg=60, tiempo_inicializacion=5, actualizacion_hz=50, usb=TRUE, usb_c=TRUE, bateria_interna=TRUE, bateria_intercambiable=NULL, bateria_caliente=NULL, auditoria_fuente='X1 Lite GNSS Receiver.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='Inicialización RTK <5 s, no encendido. Rango IMU 60°. La expansión de memoria es capacidad soportada, no instalada. No inferir baterías de repuesto. Catálogo oficial confirma batería integrada. Intercambio y cambio en caliente no declarados. UHF mejorada LoRa Tx/Rx; protocolo de otras marcas Rx o módulo normal opcional: confirmar variante.' WHERE id_equipo='GNSS-SINGULARXYZ-X1-LITE';
