UPDATE base_evaluacion SET inclinacion_imu_deg=60, tiempo_inicializacion=5, actualizacion_hz=50, usb=TRUE, usb_c=TRUE, auditoria_fuente='Z1 GNSS Receiver.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='Inicialización RTK <5 s, no encendido. Rango IMU 60°. La expansión de memoria es capacidad soportada, no instalada. No inferir baterías de repuesto. 15 km en condiciones óptimas con LoRa; no equivale a alcance garantizado con otra marca.' WHERE id_equipo='GNSS-SINGULARXYZ-Z1';
UPDATE equipos SET anio_modelo=2024 WHERE id_equipo='GNSS-SINGULARXYZ-Z1';
UPDATE base_evaluacion SET laser=TRUE, tiene_ppp=TRUE, lte_4g=NULL, sim_4g=NULL, bateria_intercambiable=NULL, inclinacion_imu_deg=120, actualizacion_hz=20, usb=TRUE, usb_c=TRUE, largo_static_horizontal_mm=2.5, largo_static_vertical_mm=3.5, largo_static_ppm_h=0.1, largo_static_ppm_v=0.4, auditoria_fuente='SinoGNSS Jupiter Laser RTK_ESP.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='Láser y 2 cámaras de 2 MP; IMU hasta 120°. PPP B2b/HAS opcional. Puerto Tipo-C. Módem celular y batería intercambiable no declarados para el receptor en esta ficha; el 4G al pie de p.2 pertenece al R80. 15 km con SNLonglink ideal.' WHERE id_equipo='GNSS-SINOGNSS-JUPITER';
UPDATE equipos SET anio_modelo=2025 WHERE id_equipo='GNSS-SINOGNSS-JUPITER';
UPDATE base_evaluacion SET tiene_ppp=TRUE, bateria_caliente=NULL, inclinacion_imu_deg=60, actualizacion_hz=20, auditoria_fuente='SinoGNSS Mars Pro Laser RTK.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='RTK de red y línea base separados. PPP mencionada sin precisión numérica. SNLonglink confirmado en página oficial actual, distinto a protocolos de ficha 2024. Cambio de baterías en caliente no declarado en ficha. Confirmar módulo UHF/4G ofertado.' WHERE id_equipo='GNSS-SINOGNSS-MARS-PRO';
UPDATE equipos SET anio_modelo=2023 WHERE id_equipo='GNSS-SINOGNSS-MARS-PRO';
