UPDATE equipos SET anio_modelo=NULL WHERE id_equipo='GNSS-SINOGNSS-P6H';
UPDATE base_evaluacion SET tiene_snlonglink=TRUE, inclinacion_imu_deg=60, actualizacion_hz=20, usb=TRUE, rs232=TRUE, auditoria_fuente='SinoGNSS T300 Plus GNSS Receiver.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='Ficha revisión 2025; modelo anterior con actualización K8/IMU en 2022. 14 h típicas, dos baterías intercambiables en caliente. 32 GB es opción de fábrica. Alcance 15 km ideal SNLonglink. No declara precisión distinta para RTK en red. Año exacto de lanzamiento pendiente; no usar año de revisión de ficha.' WHERE id_equipo='GNSS-SINOGNSS-T300PLUS';
UPDATE equipos SET anio_modelo=NULL WHERE id_equipo='GNSS-SINOGNSS-T300PLUS';
UPDATE base_evaluacion SET peso_max=1000, autonomia_bateria=NULL, tiene_imu=NULL, tiempo_inicializacion=8, radio_frecuencia='410-470 MHz', actualizacion_hz=NULL, usb=TRUE, rs232=TRUE, red_rtk_horizontal_mm=8, red_rtk_vertical_mm=15, red_rtk_ppm_h=0.5, red_rtk_ppm_v=0.5, largo_static_horizontal_mm=2.5, largo_static_vertical_mm=5, largo_static_ppm_h=0.5, largo_static_ppm_v=0.5, auditoria_fuente='ficha_Tecnica_Southern_Galaxy_G1.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='1 kg con batería. Módulo estándar 220 canales; 555/965 opcionales. Sensor de inclinación 30° opcional, no IMU de 60° confirmada. No declara autonomía. Red H8/V15 +0.5ppm. Estático de observaciones largas H2.5/V5 +0.5ppm.' WHERE id_equipo='GNSS-SOUTH-G1';
UPDATE base_evaluacion SET peso_max=1440, tiene_ppp=TRUE, ppp_h_cm=10, ppp_v_cm=20, tiene_imu=NULL, bateria_caliente=NULL, actualizacion_hz=50, usb=TRUE, rs232=TRUE, auditoria_fuente='ficha_tecnica_South_Galaxy_G6.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='1.44 kg con batería; 336 canales estándar, 965 opcionales. Hasta 50 Hz. PPP/RTX requiere suscripción. Tabla de sensor inclinación 30°, texto shake tilt sin límite: confirmar versión. Cambio en caliente no declarado.' WHERE id_equipo='GNSS-SOUTH-G6';
UPDATE base_evaluacion SET peso_max=1120, tiempo_inicializacion=8, tiene_ppp=TRUE, ppp_h_cm=2, ppp_v_cm=3, inclinacion_imu_deg=40, actualizacion_hz=20, usb=TRUE, rs232=TRUE, largo_static_horizontal_mm=3, largo_static_vertical_mm=3.5, largo_static_ppm_h=0.1, largo_static_ppm_v=0.4, auditoria_fuente='022516-511H_Trimble R12i GNSS Receiver.pdf; páginas 1–4; auditoría 2026-09-18.', auditoria_notas='1.12 kg con batería/radio/antena; 6 h Tx 0.5 W, 5.5 h Tx 2 W y 6.5 h Rx. Inicialización RTK 2–8 s. TIP precisión especificada hasta 40°. RTX H2/V3 cm con servicio. Módem según variante/región.' WHERE id_equipo='GNSS-TRIMBLE-R12I';
UPDATE equipos SET anio_modelo=2020 WHERE id_equipo='GNSS-TRIMBLE-R12I';
UPDATE base_evaluacion SET peso_max=1520, alto_mm=104, autonomia_bateria=5, tiempo_inicializacion=8, actualizacion_hz=20, rs232=TRUE, largo_static_horizontal_mm=3, largo_static_vertical_mm=3.5, largo_static_ppm_h=0.1, largo_static_ppm_v=0.4, auditoria_fuente='Datasheet-Trimble-R8s-GNSS-System-English-USL-Screen.pdf; páginas 1–2; auditoría 2026-09-18.', auditoria_notas='1.52 kg con batería/radio/antena; altura 104 mm incluidos conectores. Autonomía Rx5 h, Tx0.5 W2.5 h, celular4 h: se usa Rx5. Inicialización típicamente <8 s. GSM/3G opcional, no LTE. Sin declaración de Wi-Fi/USB en puertos: confirmar.' WHERE id_equipo='GNSS-TRIMBLE-R8S';
UPDATE equipos SET anio_modelo=2015 WHERE id_equipo='GNSS-TRIMBLE-R8S';
