UPDATE equipos SET anio_modelo=2022 WHERE id_equipo='SINOGNSS-R60';
UPDATE controladora_especificaciones SET brujula=TRUE, carga_h=NULL, notas='Autonomía 30+ h, condiciones no especificadas. Caída sobre concreto. USB 3.0, UART TTL, auriculares digitales. Carga contradictoria: 5 h en página 1 y no más de 4 h en página 2; tiempo de carga sin valor. Frecuencia CPU no declarada. Auditoría 2026-09-18: Revisadas páginas 1–2, versión 02-08-2022: Android12, RAM4/ROM64, pantalla5.5, 30+ h, IP67, caída1.6m, brújula electrónica. Carga: texto5 h frente a tabla≤4 h; se mantiene desconocida hasta confirmar. CPU GHz no declarada.' WHERE id_equipo='SINOGNSS-R60';
